"""Loans, one file per lent title, claimed with an exclusive create."""
import hashlib
import json
import os
import time
from pathlib import Path

UNKNOWN = "(unknown)"
_RETRIES = 20
_DELAY = 0.05


class AlreadyLent(Exception):
    """The title is already held by someone."""

    def __init__(self, holder):
        super().__init__(holder)
        self.holder = holder


def loans_dir():
    d = Path(os.environ.get("SHELF_HOME", ".shelf")) / "loans"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _path(title):
    return loans_dir() / (hashlib.sha256(title.encode("utf-8")).hexdigest() + ".loan")


def lend(title, member):
    """Claim the title for member, or raise AlreadyLent."""
    path = _path(title)
    flags = os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_BINARY", 0)
    for i in range(_RETRIES):
        try:
            fd = os.open(path, flags, 0o644)
            break
        except FileExistsError:
            raise AlreadyLent(holder(title) or UNKNOWN)
        except PermissionError:
            # Windows: a delete may still be pending on this path.
            if i == _RETRIES - 1:
                raise AlreadyLent(holder(title) or UNKNOWN)
            time.sleep(_DELAY)
    try:
        data = json.dumps({"title": title, "member": member}).encode("utf-8")
        os.write(fd, data)
        os.fsync(fd)
    finally:
        os.close(fd)


def give_back(title):
    """Free the title. False if it was not lent."""
    path = _path(title)
    for i in range(_RETRIES):
        try:
            os.remove(path)
            return True
        except FileNotFoundError:
            return False
        except PermissionError:
            if i == _RETRIES - 1:
                raise
            time.sleep(_DELAY)


def holder(title):
    """The member holding title, None if not lent, "(unknown)" if unreadable."""
    try:
        raw = _path(title).read_bytes()
    except FileNotFoundError:
        return None
    except OSError:
        return UNKNOWN
    try:
        return json.loads(raw.decode("utf-8"))["member"]
    except (ValueError, KeyError, TypeError):
        return UNKNOWN

